CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login address and the identity a certificate is issued against.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name as printed on certificates. Changing it after issuance does not reprint old ones.
	"full_name" VARCHAR(160) NOT NULL,
	-- When identity was confirmed for verified certificates. Null means certificates are unverified.
	"name_verified_at" TIMESTAMPTZ,
	-- ISO 3166-1 alpha-2. Drives pricing, tax and financial-aid eligibility.
	"country_code" CHAR(2),
	-- Preferred interface and subtitle language.
	"locale" VARCHAR(12) NOT NULL DEFAULT 'en',
	-- Instructor flag. One table for everyone because a learner on one course frequently teaches another.
	"can_teach" BOOLEAN NOT NULL DEFAULT false,
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'Anyone with an account, learner or instructor. Kept as one table because the overlap is large and permissions are per course, not global.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login address and the identity a certificate is issued against.';
COMMENT ON COLUMN "users"."full_name" IS 'Name as printed on certificates. Changing it after issuance does not reprint old ones.';
COMMENT ON COLUMN "users"."name_verified_at" IS 'When identity was confirmed for verified certificates. Null means certificates are unverified.';
COMMENT ON COLUMN "users"."country_code" IS 'ISO 3166-1 alpha-2. Drives pricing, tax and financial-aid eligibility.';
COMMENT ON COLUMN "users"."locale" IS 'Preferred interface and subtitle language.';
COMMENT ON COLUMN "users"."can_teach" IS 'Instructor flag. One table for everyone because a learner on one course frequently teaches another.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "courses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- URL segment. Stable across every version and every run, because it is what search engines and links point at.
	"slug" VARCHAR(120) NOT NULL UNIQUE,
	-- Catalogue title.
	"title" VARCHAR(200) NOT NULL,
	-- University or company presenting the course. Denormalised for the catalogue listing.
	"partner_name" VARCHAR(160) NOT NULL,
	-- Primary instructor shown in the catalogue. Null while a course is being built.
	"lead_instructor_id" BIGINT,
	-- Top-level catalogue subject, e.g. data-science.
	"subject" VARCHAR(80) NOT NULL,
	-- session | self_paced. Self-paced courses still have exactly one open session so every enrolment has a parent.
	"pacing" VARCHAR(16) NOT NULL DEFAULT 'session',
	-- First public availability. Null while unlisted.
	"published_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "courses" IS 'The catalogue entry and the stable identity. It deliberately holds no content: what is taught lives in a version, and when it is taught lives in a session.';
COMMENT ON COLUMN "courses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "courses"."slug" IS 'URL segment. Stable across every version and every run, because it is what search engines and links point at.';
COMMENT ON COLUMN "courses"."title" IS 'Catalogue title.';
COMMENT ON COLUMN "courses"."partner_name" IS 'University or company presenting the course. Denormalised for the catalogue listing.';
COMMENT ON COLUMN "courses"."lead_instructor_id" IS 'Primary instructor shown in the catalogue. Null while a course is being built.';
COMMENT ON COLUMN "courses"."subject" IS 'Top-level catalogue subject, e.g. data-science.';
COMMENT ON COLUMN "courses"."pacing" IS 'session | self_paced. Self-paced courses still have exactly one open session so every enrolment has a parent.';
COMMENT ON COLUMN "courses"."published_at" IS 'First public availability. Null while unlisted.';

CREATE INDEX "idx_courses_subject_published"
ON "courses" ("subject", "published_at");

CREATE TABLE IF NOT EXISTS "course_versions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Course this version belongs to.
	"course_id" BIGINT NOT NULL,
	-- Monotonic per course. Incremented when the outline changes in a way that affects grading.
	"version_number" INTEGER NOT NULL,
	-- draft | published | archived. Only a published version may be attached to a session.
	"state" VARCHAR(16) NOT NULL DEFAULT 'draft',
	-- What changed and why. Read by staff deciding whether to migrate a running cohort.
	"changelog" TEXT,
	-- Advertised workload. Per version because rewrites change it.
	"estimated_hours" NUMERIC(5,1),
	-- When this version was frozen. Null while still draft; after this, content edits mean a new version.
	"published_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "course_versions" IS 'An immutable snapshot of what the course teaches. Versioning content rather than editing in place is what lets a learner who started in March be graded on the March syllabus after an April rewrite.';
COMMENT ON COLUMN "course_versions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "course_versions"."course_id" IS 'Course this version belongs to.';
COMMENT ON COLUMN "course_versions"."version_number" IS 'Monotonic per course. Incremented when the outline changes in a way that affects grading.';
COMMENT ON COLUMN "course_versions"."state" IS 'draft | published | archived. Only a published version may be attached to a session.';
COMMENT ON COLUMN "course_versions"."changelog" IS 'What changed and why. Read by staff deciding whether to migrate a running cohort.';
COMMENT ON COLUMN "course_versions"."estimated_hours" IS 'Advertised workload. Per version because rewrites change it.';
COMMENT ON COLUMN "course_versions"."published_at" IS 'When this version was frozen. Null while still draft; after this, content edits mean a new version.';

CREATE UNIQUE INDEX "uq_course_versions_course_number"
ON "course_versions" ("course_id", "version_number");

CREATE TABLE IF NOT EXISTS "course_sessions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Content this run teaches. A run is pinned to one version for its whole life.
	"course_version_id" BIGINT NOT NULL,
	-- Human label for the run, e.g. 2026-03-02. Shown in support tickets.
	"session_code" VARCHAR(40) NOT NULL,
	-- First day of the cohort. Deadlines are computed as offsets from this date.
	"starts_on" DATE NOT NULL,
	-- Last day content is taught.
	"ends_on" DATE NOT NULL,
	-- Absolute cut-off for submissions. Null when the run has soft deadlines only.
	"hard_deadline_at" TIMESTAMPTZ,
	-- Last day to join. Null means joining stays open for the whole run.
	"enrollment_closes_on" DATE,
	-- False once archived. Self-paced courses keep one active session open indefinitely.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "course_sessions" IS 'One dated run of one content version. Separating the run from the content is what allows the same syllabus to be taught to twenty cohorts with twenty deadline calendars.';
COMMENT ON COLUMN "course_sessions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "course_sessions"."course_version_id" IS 'Content this run teaches. A run is pinned to one version for its whole life.';
COMMENT ON COLUMN "course_sessions"."session_code" IS 'Human label for the run, e.g. 2026-03-02. Shown in support tickets.';
COMMENT ON COLUMN "course_sessions"."starts_on" IS 'First day of the cohort. Deadlines are computed as offsets from this date.';
COMMENT ON COLUMN "course_sessions"."ends_on" IS 'Last day content is taught.';
COMMENT ON COLUMN "course_sessions"."hard_deadline_at" IS 'Absolute cut-off for submissions. Null when the run has soft deadlines only.';
COMMENT ON COLUMN "course_sessions"."enrollment_closes_on" IS 'Last day to join. Null means joining stays open for the whole run.';
COMMENT ON COLUMN "course_sessions"."is_active" IS 'False once archived. Self-paced courses keep one active session open indefinitely.';

CREATE UNIQUE INDEX "uq_sessions_version_code"
ON "course_sessions" ("course_version_id", "session_code");
CREATE INDEX "idx_sessions_start"
ON "course_sessions" ("starts_on");

CREATE TABLE IF NOT EXISTS "course_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Version this item belongs to. Items are copied, never moved, when a new version is cut.
	"course_version_id" BIGINT NOT NULL,
	-- Enclosing module. Null makes the row a top-level module, which is what turns this table into the course outline tree.
	"parent_item_id" BIGINT,
	-- module | lecture | reading | quiz | peer_assignment. The outline is one ordered list whatever the learner clicks.
	"item_kind" VARCHAR(20) NOT NULL,
	-- Displayed title.
	"title" VARCHAR(200) NOT NULL,
	-- Position among siblings. Gapped integers so an item can be inserted without renumbering a module.
	"ordinal" INTEGER NOT NULL,
	-- Video or reading asset. Null for modules and for gradable items, which carry no media of their own.
	"content_url" VARCHAR(500),
	-- Video length, used for the progress bar and workload estimates. Null for non-video items.
	"duration_seconds" INTEGER,
	-- True for quizzes and peer assignments. Lets the grade calculation filter the outline in one pass.
	"is_graded" BOOLEAN NOT NULL DEFAULT false,
	-- Contribution to the final grade. Null when not graded; the graded items in a version should total 100.
	"weight_percent" NUMERIC(5,2),
	-- Score needed to pass this item. Null when not graded.
	"pass_threshold_percent" NUMERIC(5,2),
	-- Attempt cap for quizzes. Null means unlimited, which is normal for practice quizzes.
	"max_attempts" SMALLINT,
	-- How many questions a quiz attempt draws from the bank. Null means serve every question in the bank.
	"questions_drawn" SMALLINT,
	-- Deadline as days after the session start. Stored as an offset so one outline serves every cohort.
	"due_offset_days" SMALLINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "course_items" IS 'Every node of the course outline — modules, lectures, readings, quizzes and peer assignments alike. One table because the learner experiences one ordered sequence, and because progress and deadlines then need only one foreign key instead of five.';
COMMENT ON COLUMN "course_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "course_items"."course_version_id" IS 'Version this item belongs to. Items are copied, never moved, when a new version is cut.';
COMMENT ON COLUMN "course_items"."parent_item_id" IS 'Enclosing module. Null makes the row a top-level module, which is what turns this table into the course outline tree.';
COMMENT ON COLUMN "course_items"."item_kind" IS 'module | lecture | reading | quiz | peer_assignment. The outline is one ordered list whatever the learner clicks.';
COMMENT ON COLUMN "course_items"."title" IS 'Displayed title.';
COMMENT ON COLUMN "course_items"."ordinal" IS 'Position among siblings. Gapped integers so an item can be inserted without renumbering a module.';
COMMENT ON COLUMN "course_items"."content_url" IS 'Video or reading asset. Null for modules and for gradable items, which carry no media of their own.';
COMMENT ON COLUMN "course_items"."duration_seconds" IS 'Video length, used for the progress bar and workload estimates. Null for non-video items.';
COMMENT ON COLUMN "course_items"."is_graded" IS 'True for quizzes and peer assignments. Lets the grade calculation filter the outline in one pass.';
COMMENT ON COLUMN "course_items"."weight_percent" IS 'Contribution to the final grade. Null when not graded; the graded items in a version should total 100.';
COMMENT ON COLUMN "course_items"."pass_threshold_percent" IS 'Score needed to pass this item. Null when not graded.';
COMMENT ON COLUMN "course_items"."max_attempts" IS 'Attempt cap for quizzes. Null means unlimited, which is normal for practice quizzes.';
COMMENT ON COLUMN "course_items"."questions_drawn" IS 'How many questions a quiz attempt draws from the bank. Null means serve every question in the bank.';
COMMENT ON COLUMN "course_items"."due_offset_days" IS 'Deadline as days after the session start. Stored as an offset so one outline serves every cohort.';

CREATE INDEX "idx_items_outline_order"
ON "course_items" ("course_version_id", "parent_item_id", "ordinal");
CREATE INDEX "idx_items_graded"
ON "course_items" ("course_version_id", "is_graded");

CREATE TABLE IF NOT EXISTS "quiz_questions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Quiz item this question belongs to. The set of rows is the question bank for that quiz.
	"item_id" BIGINT NOT NULL,
	-- Sub-pool label, e.g. week-1-regression. An attempt draws a fixed number from each pool so every learner gets comparable coverage.
	"pool_tag" VARCHAR(60),
	-- single_choice | multiple_choice | numeric | short_answer. Determines how answer_key is interpreted.
	"question_kind" VARCHAR(24) NOT NULL,
	-- Question text as shown, including any markup.
	"prompt" TEXT NOT NULL,
	-- Ordered option list for choice questions. Null for numeric and short-answer questions, which have no options.
	"choices" JSONB,
	-- Correct response plus tolerance for numeric questions. Kept out of the choices array so an API can return the question without leaking the answer.
	"answer_key" JSONB NOT NULL,
	-- Weight within the quiz. Not every question in a bank is worth the same.
	"points" NUMERIC(6,2) NOT NULL DEFAULT 1,
	-- Feedback shown after grading. Null when the instructor gives none.
	"explanation" TEXT,
	-- True when a question is withdrawn. Retired rather than deleted so old attempts still resolve their questions.
	"is_retired" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "quiz_questions" IS 'The bank a quiz draws from. Randomisation is a property of the attempt, not the quiz: the bank is fixed content, and which subset a learner saw is recorded on their attempt.';
COMMENT ON COLUMN "quiz_questions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "quiz_questions"."item_id" IS 'Quiz item this question belongs to. The set of rows is the question bank for that quiz.';
COMMENT ON COLUMN "quiz_questions"."pool_tag" IS 'Sub-pool label, e.g. week-1-regression. An attempt draws a fixed number from each pool so every learner gets comparable coverage.';
COMMENT ON COLUMN "quiz_questions"."question_kind" IS 'single_choice | multiple_choice | numeric | short_answer. Determines how answer_key is interpreted.';
COMMENT ON COLUMN "quiz_questions"."prompt" IS 'Question text as shown, including any markup.';
COMMENT ON COLUMN "quiz_questions"."choices" IS 'Ordered option list for choice questions. Null for numeric and short-answer questions, which have no options.';
COMMENT ON COLUMN "quiz_questions"."answer_key" IS 'Correct response plus tolerance for numeric questions. Kept out of the choices array so an API can return the question without leaking the answer.';
COMMENT ON COLUMN "quiz_questions"."points" IS 'Weight within the quiz. Not every question in a bank is worth the same.';
COMMENT ON COLUMN "quiz_questions"."explanation" IS 'Feedback shown after grading. Null when the instructor gives none.';
COMMENT ON COLUMN "quiz_questions"."is_retired" IS 'True when a question is withdrawn. Retired rather than deleted so old attempts still resolve their questions.';

CREATE INDEX "idx_quiz_questions_item_pool"
ON "quiz_questions" ("item_id", "pool_tag");

CREATE TABLE IF NOT EXISTS "rubric_criteria" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Peer-graded assignment this criterion belongs to.
	"item_id" BIGINT NOT NULL,
	-- Display order in the grading form.
	"ordinal" SMALLINT NOT NULL,
	-- What the grader is judging, e.g. Clarity of the research question.
	"title" VARCHAR(200) NOT NULL,
	-- Instructions telling a peer how to distinguish the levels. The single biggest lever on grading consistency.
	"guidance" TEXT,
	-- Ordered levels with their point values and labels. JSON because scales vary from yes/no to a five-level descriptive rubric.
	"scale_points" JSONB NOT NULL,
	-- Highest value on the scale, denormalised so an assignment total can be checked without parsing the JSON.
	"max_points" NUMERIC(6,2) NOT NULL,
	-- False for optional written feedback rows that carry no score.
	"is_required" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "rubric_criteria" IS 'One line of the grading form for a peer assignment. Criteria are rows rather than a blob so scores can be aggregated per criterion, which is how you find out that one rubric line is where graders disagree.';
COMMENT ON COLUMN "rubric_criteria"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "rubric_criteria"."item_id" IS 'Peer-graded assignment this criterion belongs to.';
COMMENT ON COLUMN "rubric_criteria"."ordinal" IS 'Display order in the grading form.';
COMMENT ON COLUMN "rubric_criteria"."title" IS 'What the grader is judging, e.g. Clarity of the research question.';
COMMENT ON COLUMN "rubric_criteria"."guidance" IS 'Instructions telling a peer how to distinguish the levels. The single biggest lever on grading consistency.';
COMMENT ON COLUMN "rubric_criteria"."scale_points" IS 'Ordered levels with their point values and labels. JSON because scales vary from yes/no to a five-level descriptive rubric.';
COMMENT ON COLUMN "rubric_criteria"."max_points" IS 'Highest value on the scale, denormalised so an assignment total can be checked without parsing the JSON.';
COMMENT ON COLUMN "rubric_criteria"."is_required" IS 'False for optional written feedback rows that carry no score.';

CREATE UNIQUE INDEX "uq_rubric_criteria_item_ordinal"
ON "rubric_criteria" ("item_id", "ordinal");

CREATE TABLE IF NOT EXISTS "entitlements" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Person who holds the right to graded access.
	"user_id" BIGINT NOT NULL,
	-- Course covered. Null for a subscription, which covers the whole catalogue — that null is the difference between the two products.
	"course_id" BIGINT,
	-- subscription | one_off_purchase | financial_aid | employer_sponsored | audit.
	"kind" VARCHAR(20) NOT NULL,
	-- active | expired | refunded | cancelled.
	"state" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- When graded access begins.
	"starts_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When it lapses. Null for a one-off purchase, which is perpetual for that course.
	"ends_at" TIMESTAMPTZ,
	-- Price paid in minor units. Null for financial aid and audit, which is how free access is told apart from a zero-priced sale.
	"amount_minor" INTEGER,
	-- ISO 4217 code for amount_minor. Null exactly when amount_minor is null.
	"currency_code" CHAR(3),
	-- Payment processor reference. Unique so a replayed webhook cannot grant access twice.
	"external_payment_ref" VARCHAR(120) UNIQUE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "entitlements" IS 'The right to graded access, which is not the same as being enrolled. A subscription is one row covering everything; a purchase is one row covering one course; auditing is a row too, so the reason someone has access is always explicit.';
COMMENT ON COLUMN "entitlements"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "entitlements"."user_id" IS 'Person who holds the right to graded access.';
COMMENT ON COLUMN "entitlements"."course_id" IS 'Course covered. Null for a subscription, which covers the whole catalogue — that null is the difference between the two products.';
COMMENT ON COLUMN "entitlements"."kind" IS 'subscription | one_off_purchase | financial_aid | employer_sponsored | audit.';
COMMENT ON COLUMN "entitlements"."state" IS 'active | expired | refunded | cancelled.';
COMMENT ON COLUMN "entitlements"."starts_at" IS 'When graded access begins.';
COMMENT ON COLUMN "entitlements"."ends_at" IS 'When it lapses. Null for a one-off purchase, which is perpetual for that course.';
COMMENT ON COLUMN "entitlements"."amount_minor" IS 'Price paid in minor units. Null for financial aid and audit, which is how free access is told apart from a zero-priced sale.';
COMMENT ON COLUMN "entitlements"."currency_code" IS 'ISO 4217 code for amount_minor. Null exactly when amount_minor is null.';
COMMENT ON COLUMN "entitlements"."external_payment_ref" IS 'Payment processor reference. Unique so a replayed webhook cannot grant access twice.';

CREATE INDEX "idx_entitlements_user_course"
ON "entitlements" ("user_id", "course_id", "state");

CREATE TABLE IF NOT EXISTS "enrollments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Learner.
	"user_id" BIGINT NOT NULL,
	-- Run being taken. Joining a later run of the same course creates a new enrolment rather than reusing this one.
	"session_id" BIGINT NOT NULL,
	-- Entitlement that pays for graded access. Null for an auditing learner, who can watch but not be graded.
	"entitlement_id" BIGINT,
	-- active | completed | deferred | withdrawn.
	"state" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Join time, used to compute personal deadlines on self-paced runs.
	"enrolled_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When every required item was passed. Null until then; setting it is what makes a certificate issuable.
	"completed_at" TIMESTAMPTZ,
	-- Weighted total across graded items. Recomputed on each grade change and snapshotted here for the dashboard.
	"grade_percent" NUMERIC(5,2),
	-- Local date of the most recent activity, used for re-engagement mail and for detecting silent dropout.
	"last_active_on" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "enrollments" IS 'One learner in one run. This is the row everything a learner does hangs off — progress, attempts and peer reviews all reference the enrolment, not the user, so retaking a course never mixes two attempts at the same material.';
COMMENT ON COLUMN "enrollments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "enrollments"."user_id" IS 'Learner.';
COMMENT ON COLUMN "enrollments"."session_id" IS 'Run being taken. Joining a later run of the same course creates a new enrolment rather than reusing this one.';
COMMENT ON COLUMN "enrollments"."entitlement_id" IS 'Entitlement that pays for graded access. Null for an auditing learner, who can watch but not be graded.';
COMMENT ON COLUMN "enrollments"."state" IS 'active | completed | deferred | withdrawn.';
COMMENT ON COLUMN "enrollments"."enrolled_at" IS 'Join time, used to compute personal deadlines on self-paced runs.';
COMMENT ON COLUMN "enrollments"."completed_at" IS 'When every required item was passed. Null until then; setting it is what makes a certificate issuable.';
COMMENT ON COLUMN "enrollments"."grade_percent" IS 'Weighted total across graded items. Recomputed on each grade change and snapshotted here for the dashboard.';
COMMENT ON COLUMN "enrollments"."last_active_on" IS 'Local date of the most recent activity, used for re-engagement mail and for detecting silent dropout.';

CREATE UNIQUE INDEX "uq_enrollments_user_session"
ON "enrollments" ("user_id", "session_id");
CREATE INDEX "idx_enrollments_session_state"
ON "enrollments" ("session_id", "state");

CREATE TABLE IF NOT EXISTS "item_progress" (
	-- Enrolment the progress belongs to. Half of the composite primary key.
	"enrollment_id" BIGINT,
	-- Outline item. The other half; one row per item per enrolment, so the key makes progress writes idempotent.
	"item_id" BIGINT,
	-- started | completed | skipped.
	"state" VARCHAR(16) NOT NULL DEFAULT 'started',
	-- Furthest point reached in a video. Monotonic, so rewatching never reduces it.
	"watched_seconds" INTEGER NOT NULL DEFAULT 0,
	-- When the learner first opened the item.
	"first_started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the completion rule was satisfied. Null while still in progress.
	"completed_at" TIMESTAMPTZ,
	PRIMARY KEY("enrollment_id", "item_id")
);

COMMENT ON TABLE "item_progress" IS 'One row per enrolment per item. Course-level percentages are a count over these rows rather than a counter on the enrolment, because a version change can add or remove items and a stored percentage would then be quietly wrong.';
COMMENT ON COLUMN "item_progress"."enrollment_id" IS 'Enrolment the progress belongs to. Half of the composite primary key.';
COMMENT ON COLUMN "item_progress"."item_id" IS 'Outline item. The other half; one row per item per enrolment, so the key makes progress writes idempotent.';
COMMENT ON COLUMN "item_progress"."state" IS 'started | completed | skipped.';
COMMENT ON COLUMN "item_progress"."watched_seconds" IS 'Furthest point reached in a video. Monotonic, so rewatching never reduces it.';
COMMENT ON COLUMN "item_progress"."first_started_at" IS 'When the learner first opened the item.';
COMMENT ON COLUMN "item_progress"."completed_at" IS 'When the completion rule was satisfied. Null while still in progress.';

CREATE INDEX "idx_item_progress_item_state"
ON "item_progress" ("item_id", "state");

CREATE TABLE IF NOT EXISTS "assessment_attempts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Enrolment making the attempt.
	"enrollment_id" BIGINT NOT NULL,
	-- Quiz or peer assignment being attempted.
	"item_id" BIGINT NOT NULL,
	-- Sequence within this enrolment and item. Checked against the item max_attempts before a new row is allowed.
	"attempt_number" SMALLINT NOT NULL DEFAULT 1,
	-- in_progress | submitted | graded | awaiting_peers | expired.
	"state" VARCHAR(20) NOT NULL DEFAULT 'in_progress',
	-- Start time. Combined with a quiz time limit to decide whether a late submit is accepted.
	"started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Submission time. Null while in progress; compared to the deadline to apply a late penalty.
	"submitted_at" TIMESTAMPTZ,
	-- The exact question ids drawn from the bank, in the order shown. Null for peer assignments. Without this a randomised quiz cannot be regraded or appealed.
	"served_question_ids" JSONB,
	-- Submitted answers keyed by question id. Null for peer assignments, whose work is a file.
	"responses" JSONB,
	-- Submitted file or text for a peer assignment. Null for quizzes.
	"artifact_url" VARCHAR(500),
	-- Machine-graded score. Null for peer assignments, which have no automatic component.
	"auto_score" NUMERIC(6,2),
	-- Median of accepted peer reviews. Null until enough reviews land.
	"peer_score" NUMERIC(6,2),
	-- The score that counts, after late penalties and any instructor override. Written once and used by the grade rollup.
	"final_score" NUMERIC(6,2),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "assessment_attempts" IS 'One attempt at one gradable item, whether it is a quiz submission or a peer-assignment upload. Unifying them means the grade rollup reads one table, and the difference shows up only in which columns are populated.';
COMMENT ON COLUMN "assessment_attempts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "assessment_attempts"."enrollment_id" IS 'Enrolment making the attempt.';
COMMENT ON COLUMN "assessment_attempts"."item_id" IS 'Quiz or peer assignment being attempted.';
COMMENT ON COLUMN "assessment_attempts"."attempt_number" IS 'Sequence within this enrolment and item. Checked against the item max_attempts before a new row is allowed.';
COMMENT ON COLUMN "assessment_attempts"."state" IS 'in_progress | submitted | graded | awaiting_peers | expired.';
COMMENT ON COLUMN "assessment_attempts"."started_at" IS 'Start time. Combined with a quiz time limit to decide whether a late submit is accepted.';
COMMENT ON COLUMN "assessment_attempts"."submitted_at" IS 'Submission time. Null while in progress; compared to the deadline to apply a late penalty.';
COMMENT ON COLUMN "assessment_attempts"."served_question_ids" IS 'The exact question ids drawn from the bank, in the order shown. Null for peer assignments. Without this a randomised quiz cannot be regraded or appealed.';
COMMENT ON COLUMN "assessment_attempts"."responses" IS 'Submitted answers keyed by question id. Null for peer assignments, whose work is a file.';
COMMENT ON COLUMN "assessment_attempts"."artifact_url" IS 'Submitted file or text for a peer assignment. Null for quizzes.';
COMMENT ON COLUMN "assessment_attempts"."auto_score" IS 'Machine-graded score. Null for peer assignments, which have no automatic component.';
COMMENT ON COLUMN "assessment_attempts"."peer_score" IS 'Median of accepted peer reviews. Null until enough reviews land.';
COMMENT ON COLUMN "assessment_attempts"."final_score" IS 'The score that counts, after late penalties and any instructor override. Written once and used by the grade rollup.';

CREATE UNIQUE INDEX "uq_attempts_enrollment_item_number"
ON "assessment_attempts" ("enrollment_id", "item_id", "attempt_number");
CREATE INDEX "idx_attempts_item_state"
ON "assessment_attempts" ("item_id", "state");

CREATE TABLE IF NOT EXISTS "peer_reviews" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Submission being graded.
	"attempt_id" BIGINT NOT NULL,
	-- Enrolment doing the grading. Pointing at the enrolment rather than the user is what keeps grading inside the cohort.
	"reviewer_enrollment_id" BIGINT NOT NULL,
	-- When the queue handed this submission to this reviewer.
	"assigned_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the assignment expires back into the queue. Null for instructor reviews, which do not expire.
	"due_at" TIMESTAMPTZ,
	-- When the review was completed. Null while outstanding, which is how the backlog is found.
	"submitted_at" TIMESTAMPTZ,
	-- peer | instructor | self. Instructor reviews override the peer median; self reviews are recorded but never scored.
	"reviewer_role" VARCHAR(16) NOT NULL DEFAULT 'peer',
	-- Points awarded per rubric criterion id. Null until submitted.
	"criterion_scores" JSONB,
	-- Sum of criterion scores, denormalised so the median can be computed without unpacking JSON.
	"total_score" NUMERIC(6,2),
	-- Free-text comment returned to the author.
	"written_feedback" TEXT,
	-- plagiarism | off_topic | wrong_language | empty. Non-null routes the submission to staff instead of counting the score.
	"flagged_reason" VARCHAR(40),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "peer_reviews" IS 'The who-grades-whom row: an assignment of one submission to one reviewer, created before any grading happens. Making the assignment a row rather than letting reviewers pick is what lets the system guarantee every submission gets reviewed and reclaim abandoned ones after due_at.';
COMMENT ON COLUMN "peer_reviews"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "peer_reviews"."attempt_id" IS 'Submission being graded.';
COMMENT ON COLUMN "peer_reviews"."reviewer_enrollment_id" IS 'Enrolment doing the grading. Pointing at the enrolment rather than the user is what keeps grading inside the cohort.';
COMMENT ON COLUMN "peer_reviews"."assigned_at" IS 'When the queue handed this submission to this reviewer.';
COMMENT ON COLUMN "peer_reviews"."due_at" IS 'When the assignment expires back into the queue. Null for instructor reviews, which do not expire.';
COMMENT ON COLUMN "peer_reviews"."submitted_at" IS 'When the review was completed. Null while outstanding, which is how the backlog is found.';
COMMENT ON COLUMN "peer_reviews"."reviewer_role" IS 'peer | instructor | self. Instructor reviews override the peer median; self reviews are recorded but never scored.';
COMMENT ON COLUMN "peer_reviews"."criterion_scores" IS 'Points awarded per rubric criterion id. Null until submitted.';
COMMENT ON COLUMN "peer_reviews"."total_score" IS 'Sum of criterion scores, denormalised so the median can be computed without unpacking JSON.';
COMMENT ON COLUMN "peer_reviews"."written_feedback" IS 'Free-text comment returned to the author.';
COMMENT ON COLUMN "peer_reviews"."flagged_reason" IS 'plagiarism | off_topic | wrong_language | empty. Non-null routes the submission to staff instead of counting the score.';

CREATE UNIQUE INDEX "uq_peer_reviews_attempt_reviewer"
ON "peer_reviews" ("attempt_id", "reviewer_enrollment_id");
CREATE INDEX "idx_peer_reviews_reviewer_queue"
ON "peer_reviews" ("reviewer_enrollment_id", "submitted_at");

CREATE TABLE IF NOT EXISTS "certificates" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Enrolment that earned it. Unique, so one completed run yields at most one certificate.
	"enrollment_id" BIGINT NOT NULL UNIQUE,
	-- Public verification code printed on the certificate and resolvable without logging in.
	"serial" VARCHAR(40) NOT NULL UNIQUE,
	-- Issue time.
	"issued_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Name snapshotted at issue. A later profile rename must not silently alter an issued document.
	"learner_name" VARCHAR(160) NOT NULL,
	-- Course title snapshotted at issue, for the same reason — a course can be retitled afterwards.
	"course_title" VARCHAR(200) NOT NULL,
	-- Grade at the moment of issue, frozen against later regrades.
	"final_grade_percent" NUMERIC(5,2) NOT NULL,
	-- True when the learner identity was confirmed. Unverified certificates are still issued but are labelled differently.
	"is_verified" BOOLEAN NOT NULL DEFAULT false,
	-- When the certificate was withdrawn, e.g. after a plagiarism finding. Null for valid certificates; rows are never deleted because the serial stays publicly resolvable.
	"revoked_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "certificates" IS 'An issued credential. Everything printed on it is snapshotted rather than joined, because the document is a statement about a moment and must not change when the catalogue does.';
COMMENT ON COLUMN "certificates"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "certificates"."enrollment_id" IS 'Enrolment that earned it. Unique, so one completed run yields at most one certificate.';
COMMENT ON COLUMN "certificates"."serial" IS 'Public verification code printed on the certificate and resolvable without logging in.';
COMMENT ON COLUMN "certificates"."issued_at" IS 'Issue time.';
COMMENT ON COLUMN "certificates"."learner_name" IS 'Name snapshotted at issue. A later profile rename must not silently alter an issued document.';
COMMENT ON COLUMN "certificates"."course_title" IS 'Course title snapshotted at issue, for the same reason — a course can be retitled afterwards.';
COMMENT ON COLUMN "certificates"."final_grade_percent" IS 'Grade at the moment of issue, frozen against later regrades.';
COMMENT ON COLUMN "certificates"."is_verified" IS 'True when the learner identity was confirmed. Unverified certificates are still issued but are labelled differently.';
COMMENT ON COLUMN "certificates"."revoked_at" IS 'When the certificate was withdrawn, e.g. after a plagiarism finding. Null for valid certificates; rows are never deleted because the serial stays publicly resolvable.';

